layer.css:
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(246, 248, 250); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid color-mix(in srgb, var(--ryt-border) 70%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 70%, transparent); border-radius: 0px; transition: background-color 0.2s; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-header-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 6px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: background-color 0.12s ease-out }
[data-ryt="button"] { color: rgb(37, 41, 46); background-color: rgb(246, 248, 250); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 6px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 500; font-style: normal; line-height: 1.667; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(37, 41, 46); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 3px; padding-right: 12px; padding-bottom: 3px; padding-left: 12px; transition: color 0.08s cubic-bezier(0.33, 1, 0.68, 1), background-color 0.08s cubic-bezier(0.33, 1, 0.68, 1), box-shadow 0.08s cubic-bezier(0.33, 1, 0.68, 1), border-color 0.08s cubic-bezier(0.33, 1, 0.68, 1) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-muted); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-muted); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 9999px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 6px; padding-bottom: 0px; padding-left: 6px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-size 0.2s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", "noto sans", Helvetica, Arial, sans-serif, "apple color emoji", "segoe ui emoji"; font-size: 20px; font-weight: 600; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, #f67717ff 80%, #ffffff) }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, #f67717ff 80%, #ffffff); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="button"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: #eff2f5 }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: color-mix(in srgb, var(--ryt-bg) 10%, transparent); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, var(--ryt-header-text) 70%, transparent) }
article[data-ryt="rec-card"]:hover { background-color: #f6f8fa }
